@font-face {
  font-family: "LXGW WenKai";
  src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/lxgwwenkai/lxgwwenkai.woff2") format("woff2");
  font-style: normal;
  font-weight: 400;
  font-display: swap;
}

:root {
  --mte-pool: #1f4ea8;
  --mte-water: #5f88d7;
  --mte-coral: #f29a8b;
  --mte-violet: #6d5a98;
  --mte-paper: #fff8eb;
  --mte-paper-soft: #f8ecdf;
  --mte-paper-edge: #e8d6cf;
  --mte-ink: #26325f;
  --mte-muted: #796f8f;
  --mte-night: #101934;
  --mte-success: #4f927d;
  --mte-warning: #b96b5a;
  --mte-focus: #ffd5a9;
  --mte-surface: #fff8eb;
  --mte-surface-muted: #e6efff;
  --mte-surface-disabled: #f6e6e1;
  --mte-text-disabled: #654f70;
  --mte-border-disabled: #d7a7b2;
  --mte-code-text: #e9efff;
  --mte-code-overflow: auto;
  --mte-filter-reset: none;
  --mte-text-shadow-reset: none;
  --mte-choice-surface: #fffaf0;
  --mte-choice-disabled-surface: #f4d8d5;
  --mte-choice-disabled-border: #9a6f91;
  --mte-select2-tag-border: #9ebbe8;
  --mte-opacity-disabled: 1;
  --mte-font: "LXGW WenKai", "Noto Serif SC", "Microsoft YaHei", serif;
  --mte-line: color-mix(in srgb, var(--mte-violet) 28%, transparent);
  --mte-paper-shadow: 0 14px 34px rgba(34, 41, 91, 0.16);
  --mte-control-shadow: 0 4px 14px rgba(25, 43, 105, 0.2);
  --mte-frost: blur(11px) saturate(118%);
  --mte-asset-main: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2d6f8dd07077f9977c39524a65fc3c9b47da753a/assets/%E6%9A%AE%E6%BD%AE%E5%9B%9E%E5%A3%B0/%E6%9A%AE%E6%BD%AE%E5%9B%9E%E5%A3%B0-%E5%9B%BA%E5%AE%9A%E6%A2%A6%E6%A0%B8%E4%B8%BB%E8%A7%86%E8%A7%89-v2.png");
  --mte-object-key: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2d6f8dd07077f9977c39524a65fc3c9b47da753a/assets/%E6%9A%AE%E6%BD%AE%E5%9B%9E%E5%A3%B0/small-objects/top-textgen-moon-dial-v9.png");
  --mte-object-api: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2d6f8dd07077f9977c39524a65fc3c9b47da753a/assets/%E6%9A%AE%E6%BD%AE%E5%9B%9E%E5%A3%B0/small-objects/top-api-signal-buoy-v9.png");
  --mte-object-format: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2d6f8dd07077f9977c39524a65fc3c9b47da753a/assets/%E6%9A%AE%E6%BD%AE%E5%9B%9E%E5%A3%B0/small-objects/top-format-ribbons-v9.png");
  --mte-object-world: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2d6f8dd07077f9977c39524a65fc3c9b47da753a/assets/%E6%9A%AE%E6%BD%AE%E5%9B%9E%E5%A3%B0/small-objects/top-world-archipelago-v9.png");
  --mte-object-settings: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2d6f8dd07077f9977c39524a65fc3c9b47da753a/assets/%E6%9A%AE%E6%BD%AE%E5%9B%9E%E5%A3%B0/small-objects/top-settings-moon-compass-v9.png");
  --mte-object-background: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2d6f8dd07077f9977c39524a65fc3c9b47da753a/assets/%E6%9A%AE%E6%BD%AE%E5%9B%9E%E5%A3%B0/small-objects/top-background-portal-v9.png");
  --mte-object-extensions: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2d6f8dd07077f9977c39524a65fc3c9b47da753a/assets/%E6%9A%AE%E6%BD%AE%E5%9B%9E%E5%A3%B0/small-objects/top-extensions-mobile-v9.png");
  --mte-object-persona: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2d6f8dd07077f9977c39524a65fc3c9b47da753a/assets/%E6%9A%AE%E6%BD%AE%E5%9B%9E%E5%A3%B0/small-objects/top-persona-mode-tokens-v9.png");
  --mte-object-character: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/958f74f80d0f8d7f4a861b899ef7dd7e76d4037d/assets/%E6%9A%AE%E6%BD%AE%E5%9B%9E%E5%A3%B0/small-objects/user-butterfly-v1.png");
  --mte-object-reasoning: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2d6f8dd07077f9977c39524a65fc3c9b47da753a/assets/%E6%9A%AE%E6%BD%AE%E5%9B%9E%E5%A3%B0/small-objects/reasoning-maze-v9.png");
  --mte-object-menu: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2d6f8dd07077f9977c39524a65fc3c9b47da753a/assets/%E6%9A%AE%E6%BD%AE%E5%9B%9E%E5%A3%B0/small-objects/menu-waves.png");
  --mte-object-wand: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2d6f8dd07077f9977c39524a65fc3c9b47da753a/assets/%E6%9A%AE%E6%BD%AE%E5%9B%9E%E5%A3%B0/small-objects/magic-wand.png");
  --mte-object-send: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2d6f8dd07077f9977c39524a65fc3c9b47da753a/assets/%E6%9A%AE%E6%BD%AE%E5%9B%9E%E5%A3%B0/small-objects/send-boat.png");
  --mte-object-stop: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2d6f8dd07077f9977c39524a65fc3c9b47da753a/assets/%E6%9A%AE%E6%BD%AE%E5%9B%9E%E5%A3%B0/small-objects/stop-lifebuoy.png");
  --mte-object-slider: url("data:image/png;base64,");
  --mte-input-object: var(--mte-object-send);
  --mte-panel-accent: var(--mte-water);
  --avatar-size: 4.15rem;
  --avatar-gap: 0.72rem;
  --avatar-slot: 4.65rem;
  --mte-mobile-reading-width: 100%;
  --mte-mobile-reading-padding: clamp(0.08rem, 1.8vw, 0.24rem);
}

/* ===== src/kernel/base.css ===== */
body {
  background: var(--mte-night);
  color: var(--mte-ink);
}

#bg1,
#bg_custom {
  background-color: var(--mte-night);
  background-image: linear-gradient(rgba(16, 25, 52, 0.08), rgba(16, 25, 52, 0.18)), var(--mte-asset-main) !important;
  background-position: center 48%;
  background-repeat: no-repeat;
  background-size: cover;
  background-attachment: fixed;
}

#sheld {
  background: rgba(16, 25, 52, 0.08);
  box-shadow: 0 0 0 1px rgba(255, 248, 235, 0.18), 0 22px 55px rgba(10, 22, 63, 0.3);
  backdrop-filter: blur(2.5px) saturate(108%);
  -webkit-backdrop-filter: blur(2.5px) saturate(108%);
}

#chat,
#send_form,
#top-bar,
#left-nav-panel,
#right-nav-panel,
#rm_api_block,
#AdvancedFormatting,
#WorldInfo,
#user-settings-block,
#Backgrounds,
#rm_extensions_block,
#PersonaManagement,
.popup,
#completion_prompt_manager_popup {
  color: var(--mte-ink);
  text-shadow: none;
}

#chat :is(.name_text, .timestamp, .mes_text, .mes_reasoning, .mesIDDisplay, .mes_timer, .tokenCounterDisplay),
#send_textarea,
#left-nav-panel :is(input, textarea, select, button, label),
#right-nav-panel :is(input, textarea, select, button, label),
#rm_api_block :is(input, textarea, select, button, label),
#AdvancedFormatting :is(input, textarea, select, button, label),
#WorldInfo :is(input, textarea, select, button, label),
#user-settings-block :is(input, textarea, select, button, label),
#Backgrounds :is(input, textarea, select, button, label),
#rm_extensions_block :is(input, textarea, select, button, label),
#PersonaManagement :is(input, textarea, select, button, label),
.popup :is(input, textarea, select, button, label, .popup-content) {
  font-family: var(--mte-font);
}

:is(#chat, #top-bar, #send_form, #left-nav-panel, #right-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, .popup) :is(a, button, input, textarea, select, [tabindex]):focus-visible {
  outline: 2px solid var(--mte-focus);
  outline-offset: 2px;
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--mte-pool) 22%, transparent);
}

@media (prefers-reduced-motion: reduce) {
  :is(#chat, #top-bar, #send_form, .drawer-content, .popup) {
    scroll-behavior: auto;
  }
}

/* ===== src/kernel/scrollbars.css ===== */
/*
 * 暮潮回声 v9 无滚动条外观内核。
 * 只隐藏浏览器轨道和拇指，不修改 overflow、touch-action、pointer-events，
 * 不隐藏滚动容器、功能按钮或 input[type="range"]。
 */
:where(
  html,
  body,
  #sheld,
  #sheld *,
  #chat,
  .drawer-content,
  .popup-content,
  .scrollable,
  .select2-results__options,
  #send_textarea,
  #chat .mes_text pre,
  #chat .mes_text .table-responsive
) {
  scrollbar-width: none;
  -ms-overflow-style: none;
}

:where(
  html,
  body,
  #sheld,
  #sheld *,
  #chat,
  .drawer-content,
  .popup-content,
  .scrollable,
  .select2-results__options,
  #send_textarea,
  #chat .mes_text pre,
  #chat .mes_text .table-responsive
)::-webkit-scrollbar {
  width: 0;
  height: 0;
}

/* ===== src/chat-layout.css ===== */
#chat {
  gap: 0;
  padding: 0;
  background: rgba(16, 25, 52, 0.1);
  border-inline: 1px solid rgba(255, 248, 235, 0.16);
  backdrop-filter: blur(3px) saturate(108%);
  -webkit-backdrop-filter: blur(3px) saturate(108%);
  text-shadow: none;
}

#chat .mes[is_user="true"] {
  flex-direction: row-reverse;
  flex-wrap: nowrap;
}

#chat .mes {
  align-items: flex-start;
  gap: var(--avatar-gap);
  padding: clamp(0.65rem, 1.5vw, 1.05rem) clamp(0.7rem, 2.2vw, 1.4rem);
  margin: 0;
  color: var(--mte-ink);
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
}

#chat .mes + .mes {
  border-top: 1px solid rgba(255, 248, 235, 0.14);
}

#chat .mesAvatarWrapper {
  display: flex;
  flex: 0 0 var(--avatar-slot);
  width: var(--avatar-slot);
  min-width: 0;
  padding: 0.16rem 0 0 !important;
  flex-direction: column;
  align-items: center;
  gap: 0.22rem;
  color: color-mix(in srgb, var(--mte-paper) 82%, var(--mte-water));
  text-align: center;
}

#chat .mesAvatarWrapper .avatar {
  display: block !important;
  flex: 0 0 var(--avatar-size);
  width: var(--avatar-size) !important;
  height: var(--avatar-size) !important;
  max-width: var(--avatar-size);
  overflow: hidden;
  border: 2px solid var(--mte-water);
  border-radius: 1.15rem 0.38rem 1.15rem 0.38rem;
  background: rgba(255, 248, 235, 0.78);
  box-shadow: 0 5px 16px rgba(16, 25, 52, 0.28), 0 0 0 3px rgba(255, 248, 235, 0.3);
  backdrop-filter: var(--mte-frost);
  -webkit-backdrop-filter: var(--mte-frost);
}

#chat .mesAvatarWrapper .avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: inherit;
}

#chat .mes[is_user="true"] .mesAvatarWrapper .avatar {
  border-color: var(--mte-coral);
  border-radius: 0.38rem 1.15rem 0.38rem 1.15rem;
}

#chat .mesAvatarWrapper :is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay) {
  max-width: 100%;
  font-size: 0.68em;
  line-height: 1.25;
  opacity: 0.88;
  overflow-wrap: anywhere;
  filter: none;
}

#chat .mes_block {
  flex: 1 1 auto;
  min-width: 0;
  width: auto;
  padding: clamp(0.8rem, 1.8vw, 1.25rem);
  overflow-x: clip;
  overflow-y: visible;
  backdrop-filter: var(--mte-frost);
  -webkit-backdrop-filter: var(--mte-frost);
}

#chat .mes[is_user="true"] .mes_block {
  flex: 0 1 auto;
  width: min(78%, 48rem);
  max-width: min(78%, 48rem);
  background: linear-gradient(125deg, rgba(229, 239, 255, 0.78), rgba(255, 248, 235, 0.72));
  border: 1px solid color-mix(in srgb, var(--mte-water) 55%, var(--mte-paper));
  border-right: 4px solid var(--mte-coral);
  border-radius: 1.45rem 0.35rem 0.35rem 1.45rem;
  box-shadow: var(--mte-control-shadow);
}

#chat .mes[is_user="false"][is_system="false"] .mes_block {
  background: linear-gradient(180deg, rgba(255, 250, 240, 0.84), rgba(255, 246, 231, 0.78));
  border: 1px solid var(--mte-paper-edge);
  border-left: 4px solid var(--mte-water);
  border-radius: 0.35rem 1.35rem 1.35rem 0.35rem;
  box-shadow: var(--mte-paper-shadow);
}

#chat .mes[is_user="false"][is_system="false"] .ch_name::after {
  content: "";
  flex: 1 1 auto;
  min-width: 1.8rem;
  height: 0.48rem;
  margin-left: 0.2rem;
  background:
    radial-gradient(circle at 0.24rem 50%, var(--mte-coral) 0 0.16rem, transparent 0.17rem),
    linear-gradient(90deg, color-mix(in srgb, var(--mte-water) 72%, transparent), transparent);
  background-repeat: no-repeat;
  opacity: 0.82;
  pointer-events: none;
}

#chat .mes[is_system="true"] .mes_block,
#chat .smallSysMes .mes_block {
  background: rgba(237, 228, 238, 0.8);
  border: 1px dashed color-mix(in srgb, var(--mte-violet) 55%, var(--mte-paper));
  border-radius: 0.45rem;
  box-shadow: none;
}

#chat .mes_block .ch_name {
  min-height: 1.7rem;
  align-items: center;
  gap: 0.55rem;
  padding-bottom: 0.55rem;
  border-bottom: 1px solid var(--mte-line);
}

#chat .name_text {
  color: var(--mte-pool);
  font-size: 1.12em;
  font-weight: 400;
  letter-spacing: 0.055em;
}

#chat .timestamp {
  color: var(--mte-muted);
  font-size: 0.78em;
  opacity: 0.9;
}

#chat .mes_buttons,
#chat .mes_button,
#chat .mes_edit_buttons {
  color: var(--mte-violet);
  filter: none;
  text-shadow: none;
}

#chat .mes_buttons :is(.mes_button, .menu_button):hover,
#chat .mes_buttons :is(.mes_button, .menu_button):focus-visible {
  color: var(--mte-coral);
  opacity: 1;
  filter: none;
}

#chat .mes_buttons :is(.mes_button, .menu_button):focus-visible {
  outline: 2px solid var(--mte-focus);
  outline-offset: 2px;
}

#chat .mes_block .ch_name > .mes_edit_buttons {
  color: var(--mte-pool);
  opacity: 1;
  filter: none;
  text-shadow: none;
}

#chat .mes_block .ch_name > .mes_edit_buttons .menu_button {
  color: var(--mte-pool);
  background-color: rgba(255, 248, 235, 0.96);
  background-image: linear-gradient(145deg, rgba(229, 239, 255, 0.92), rgba(255, 248, 235, 0.98));
  border: 1px solid color-mix(in srgb, var(--mte-water) 54%, var(--mte-paper-edge));
  border-radius: 0.42rem;
  box-shadow: 0 2px 8px rgba(31, 78, 168, 0.14);
  opacity: 1;
  filter: none;
  text-shadow: none;
}

#chat .mes_block .ch_name > .mes_edit_buttons .mes_edit_done.menu_button {
  color: var(--mte-success);
  background-color: color-mix(in srgb, var(--mte-success) 14%, var(--mte-paper));
  background-image: none;
  border-color: color-mix(in srgb, var(--mte-success) 56%, var(--mte-paper-edge));
}

#chat .mes_block .ch_name > .mes_edit_buttons .mes_edit_cancel.menu_button {
  color: var(--mte-warning);
  background-color: color-mix(in srgb, var(--mte-coral) 18%, var(--mte-paper));
  background-image: none;
  border-color: color-mix(in srgb, var(--mte-coral) 62%, var(--mte-paper-edge));
}

#chat .mes_block .ch_name > .mes_edit_buttons .menu_button:hover {
  color: var(--mte-coral);
  background-color: color-mix(in srgb, var(--mte-water) 14%, var(--mte-paper));
  border-color: var(--mte-coral);
  box-shadow: 0 3px 10px rgba(31, 78, 168, 0.18);
  opacity: 1;
  filter: none;
  text-shadow: none;
}

#chat .mes_block .ch_name > .mes_edit_buttons .menu_button:focus-visible {
  outline: 2px solid var(--mte-focus);
  outline-offset: 2px;
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--mte-pool) 20%, transparent);
}

#chat .mes_block :is(#curEditTextarea.edit_textarea, .reasoning_edit_textarea) {
  box-sizing: border-box;
  width: 100%;
  color: var(--mte-ink);
  -webkit-text-fill-color: var(--mte-ink);
  caret-color: var(--mte-pool);
  background-color: rgba(255, 248, 235, 0.94);
  background-image:
    linear-gradient(90deg, rgba(95, 136, 215, 0.15) 0 0.28rem, transparent 0.28rem),
    linear-gradient(180deg, rgba(255, 252, 246, 0.96), rgba(229, 239, 255, 0.86));
  border: 1px solid color-mix(in srgb, var(--mte-water) 64%, var(--mte-paper-edge));
  border-radius: 0.55rem;
  box-shadow: inset 0 0 0 1px rgba(255, 248, 235, 0.7), 0 5px 16px rgba(31, 78, 168, 0.14);
  opacity: 1;
  filter: none;
  text-shadow: none;
}

#chat .mes_block :is(#curEditTextarea.edit_textarea, .reasoning_edit_textarea):focus-visible {
  color: var(--mte-ink);
  background-color: rgba(255, 252, 246, 0.98);
  border-color: var(--mte-coral);
  outline: 2px solid var(--mte-focus);
  outline-offset: 2px;
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--mte-pool) 18%, transparent), inset 0 0 0 1px var(--mte-paper);
  opacity: 1;
  filter: none;
}

#chat .mes_block :is(#curEditTextarea.edit_textarea, .reasoning_edit_textarea)::selection {
  color: var(--mte-paper);
  background: var(--mte-pool);
}

#chat .swipe_left,
#chat .swipe_right,
#chat .swipes-counter {
  color: var(--mte-paper);
  filter: none;
  text-shadow: 0 1px 4px rgba(16, 25, 52, 0.5);
}

#chat .mes.selected .mes_block {
  background-color: color-mix(in srgb, var(--mte-focus) 38%, var(--mte-paper));
  outline: 2px solid var(--mte-coral);
  outline-offset: 2px;
}

#chat .mes.selected {
  background: transparent;
}

@media (max-width: 700px) {
  #chat .mes[is_system="false"] {
    position: relative;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    padding: 0.58rem 0.46rem 0.72rem;
  }

  #chat .mes[is_system="false"] > .mesAvatarWrapper {
    position: absolute;
    inset-block-start: 1.08rem;
    inset-inline-start: 0.88rem;
    z-index: 3;
    flex: 0 0 auto;
    width: auto;
    max-width: 5.25rem;
    min-width: 0;
    padding: 0 !important;
    flex-direction: row;
    align-items: center;
    gap: 0.22rem;
    text-align: left;
  }

  #chat .mes[is_user="true"] > .mesAvatarWrapper {
    inset-inline-start: auto;
    inset-inline-end: 0.88rem;
    flex-direction: row-reverse;
    text-align: right;
  }

  #chat .mes[is_system="false"] > .mesAvatarWrapper .avatar {
    flex: 0 0 2.9rem;
    width: 2.9rem !important;
    height: 2.9rem !important;
    max-width: 2.9rem;
    border-radius: 0.96rem 0.3rem 0.96rem 0.3rem;
    box-shadow: 0 4px 12px rgba(16, 25, 52, 0.24), 0 0 0 2px rgba(255, 248, 235, 0.46);
  }

  #chat .mes[is_user="true"] > .mesAvatarWrapper .avatar {
    border-radius: 0.3rem 0.96rem 0.3rem 0.96rem;
  }

  #chat .mes[is_system="false"] > .mesAvatarWrapper .avatar img {
    object-position: center 42%;
  }

  #chat .mes[is_system="false"] > .mesAvatarWrapper :is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay) {
    width: auto;
    max-width: 2.05rem;
