  margin-inline: auto;
}

#chat .mes_text p {
  margin: 0 0 1.05em;
}

#chat .mes_text p:last-child {
  margin-bottom: 0;
}

#chat .mes_text :is(h1, h2, h3, h4, h5, h6) {
  color: var(--mte-pool);
  font-weight: 400;
  line-height: 1.35;
  letter-spacing: 0.06em;
  text-wrap: balance;
}

#chat .mes_text :is(h1, h2) {
  padding-bottom: 0.3em;
  border-bottom: 1px solid var(--mte-line);
}

#chat .mes_text blockquote {
  margin: 1em 0;
  padding: 0.55em 1em;
  color: color-mix(in srgb, var(--mte-ink) 76%, var(--mte-violet));
  background: color-mix(in srgb, var(--mte-water) 11%, var(--mte-paper));
  border-left: 3px solid var(--mte-water);
  border-radius: 0 0.55rem 0.55rem 0;
}

#chat .mes_text :is(em, i) {
  color: var(--mte-violet);
}

#chat .mes_text :is(strong, b) {
  color: var(--mte-pool);
  font-weight: 400;
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, var(--mte-coral) 62%, transparent);
  text-underline-offset: 0.18em;
}

#chat .mes_text a {
  color: var(--mte-pool);
  text-decoration-color: var(--mte-coral);
  text-underline-offset: 0.18em;
}

#chat .mes_text hr {
  height: 1px;
  margin: 1.45em auto;
  border: 0;
  opacity: 1;
  background: linear-gradient(90deg, transparent, var(--mte-water), var(--mte-coral), transparent);
}

#chat .mes_text :is(code, pre) {
  font-family: "Cascadia Mono", "Consolas", monospace;
}

#chat .mes_text code:not(pre code) {
  color: var(--mte-pool);
  background: var(--mte-surface-muted);
  border: 1px solid var(--mte-water);
  border-radius: 0.28rem;
  padding: 0.08em 0.35em;
  text-shadow: none;
}

#chat .mes_text pre {
  overflow-x: var(--mte-code-overflow);
  padding: 0.9em 1em;
  color: var(--mte-code-text);
  background: var(--mte-night);
  border: 1px solid color-mix(in srgb, var(--mte-water) 55%, var(--mte-night));
  border-radius: 0.5rem;
  box-shadow: inset 4px 0 0 var(--mte-coral);
}

#chat .mes_text pre code {
  color: inherit;
  background: transparent;
  border: 0;
  padding: 0;
}

#chat .mes_text pre code.hljs {
  color: var(--mte-code-text);
  background: var(--mte-night);
  text-shadow: none;
}

#chat .mes_text pre code.hljs :is(.hljs-subst, .hljs-punctuation, .hljs-operator) {
  color: var(--mte-code-text);
  opacity: 1;
  text-shadow: none;
}

#chat .mes_text pre code.hljs :is(.hljs-comment, .hljs-quote, .hljs-meta) {
  color: var(--mte-water);
  opacity: 1;
  text-shadow: none;
}

#chat .mes_text pre code.hljs :is(.hljs-keyword, .hljs-selector-tag, .hljs-title, .hljs-string, .hljs-number, .hljs-literal) {
  color: var(--mte-coral);
  opacity: 1;
  text-shadow: none;
}

#chat .mes_text :is(code, pre code.hljs)::selection {
  color: var(--mte-night);
  background: var(--mte-focus);
}

#chat .mes_text table {
  display: block;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
}

#chat .mes_text :is(th, td) {
  padding: 0.45em 0.7em;
  border: 1px solid var(--mte-paper-edge);
}

#chat .mes_text th {
  color: var(--mte-pool);
  background: rgba(95, 136, 215, 0.11);
  font-weight: 400;
}

#chat .mes_media_wrapper,
#chat .mes_file_wrapper {
  max-width: min(72ch, 100%);
  margin-inline: auto;
}

