}

#WorldInfo :is(.world_entry, .world_entry_form_control, .inline-drawer-content) {
  color: var(--mte-ink);
  border-color: var(--mte-paper-edge);
}

#WorldInfo .world_entry {
  background:
    linear-gradient(90deg, rgba(95, 136, 215, 0.15) 0 0.34rem, transparent 0.34rem),
    repeating-linear-gradient(0deg, transparent 0 2.4rem, rgba(95, 136, 215, 0.07) 2.4rem 2.46rem),
    rgba(255, 252, 246, 0.92);
  border-left-color: var(--mte-water);
  border-radius: 0.3rem 1rem 0.3rem 0.3rem;
  box-shadow: 0 3px 0 rgba(242, 154, 139, 0.12);
}

#WorldInfo #WIMultiSelector .select2-container .select2-selection--multiple {
  color: var(--mte-ink);
  background: rgba(255, 252, 246, 0.98);
  border-color: var(--mte-water);
  box-shadow: none;
  filter: none;
}

#WorldInfo #WIMultiSelector .select2-container--focus .select2-selection--multiple {
  border-color: var(--mte-coral);
  box-shadow: 0 0 0 3px rgba(242, 154, 139, 0.16);
}

#WorldInfo #WIMultiSelector .select2-selection__choice {
  color: var(--mte-pool) !important;
  background: var(--mte-surface-muted) !important;
  border: 1px solid var(--mte-select2-tag-border) !important;
  box-shadow: none !important;
  text-shadow: var(--mte-text-shadow-reset) !important;
  opacity: var(--mte-opacity-disabled) !important;
  filter: var(--mte-filter-reset) !important;
}

#WorldInfo #WIMultiSelector .select2-selection__choice:hover,
#WorldInfo #WIMultiSelector .select2-container--focus .select2-selection__choice {
  color: var(--mte-pool) !important;
  background: var(--mte-surface-muted) !important;
  border-color: var(--mte-coral) !important;
  opacity: var(--mte-opacity-disabled) !important;
  filter: var(--mte-filter-reset) !important;
  text-shadow: var(--mte-text-shadow-reset) !important;
}

#WorldInfo #WIMultiSelector .select2-container--focus .select2-selection__choice {
  outline: 2px solid var(--mte-focus);
  outline-offset: 2px;
}

#WorldInfo #WIMultiSelector .select2-selection__choice__display {
  color: var(--mte-pool) !important;
  opacity: var(--mte-opacity-disabled) !important;
  filter: var(--mte-filter-reset) !important;
  text-shadow: var(--mte-text-shadow-reset) !important;
}

#WorldInfo #WIMultiSelector .select2-selection__choice__remove {
  color: var(--mte-warning) !important;
  filter: var(--mte-filter-reset) !important;
  text-shadow: var(--mte-text-shadow-reset) !important;
  opacity: var(--mte-opacity-disabled) !important;
}

#WorldInfo #WIMultiSelector .select2-selection__choice__remove:hover,
#WorldInfo #WIMultiSelector .select2-selection__choice__remove:focus-visible {
  color: var(--mte-coral) !important;
}

#WorldInfo #WIMultiSelector .select2-container--disabled .select2-selection--multiple,
#WorldInfo #WIMultiSelector .select2-container--disabled .select2-selection__choice {
  color: var(--mte-text-disabled) !important;
  background: var(--mte-surface-disabled) !important;
  border-color: var(--mte-border-disabled) !important;
  opacity: var(--mte-opacity-disabled) !important;
  filter: var(--mte-filter-reset) !important;
  text-shadow: var(--mte-text-shadow-reset) !important;
}

#WorldInfo + .select2-container .select2-dropdown,
body > .select2-container .select2-dropdown {
  color: var(--mte-ink);
  background: var(--mte-paper);
  border-color: var(--mte-paper-edge);
  box-shadow: var(--mte-control-shadow);
  opacity: 1;
  filter: none;
}

/* ===== src/windows/user-settings.css ===== */
#user-settings-block {
  border-top: 3px solid #dba8c6;
}

#user-settings-block :is(#UI-Theme-Block, #UI-Customization, #power-user-options-block) {
  color: var(--mte-ink);
  background:
    linear-gradient(90deg, rgba(219, 168, 198, 0.14) 0 0.34rem, transparent 0.34rem),
    repeating-linear-gradient(0deg, transparent 0 2.5rem, rgba(95, 136, 215, 0.065) 2.5rem 2.56rem),
    rgba(255, 252, 246, 0.82);
  border-color: var(--mte-paper-edge);
  border-radius: 0.3rem 1rem 0.3rem 0.3rem;
}

#user-settings-block :is(#UI-Theme-Block, #UI-Customization) :is(h3, h4, .standoutHeader) {
  color: var(--mte-pool);
  text-shadow: none;
  filter: none;
}

#user-settings-block h4,
#user-settings-block .inline-drawer-toggle.inline-drawer-header {
  color: var(--mte-pool);
  text-shadow: none;
  filter: none;
}

#user-settings-block #customCSS {
  font-family: "Cascadia Mono", "Consolas", monospace;
  color: var(--mte-ink);
  background: #f7efe7;
}

/* ===== src/windows/backgrounds.css ===== */
#Backgrounds {
  border-top: 3px solid var(--mte-coral);
}

#Backgrounds :is(.bg_example, .bg_list) {
  border-color: var(--mte-paper-edge);
  box-shadow: none;
}

#Backgrounds .bg_example {
  background-color: var(--mte-paper-soft);
  border: 0.42rem solid var(--mte-paper);
  border-bottom-width: 1rem;
  border-radius: 0.24rem;
  box-shadow: 0 3px 0 rgba(95, 136, 215, 0.18);
}

#Backgrounds .BGSampleTitle {
  color: var(--mte-paper);
  background: rgba(16, 25, 52, 0.78);
  text-shadow: none;
}

#Backgrounds :is(.jg-button, .mobile-only-menu-toggle) {
  color: var(--mte-paper);
  background: rgba(31, 78, 168, 0.82);
  filter: none;
}

#Backgrounds .bg_list {
  background:
    radial-gradient(circle at 1rem 1rem, rgba(242, 154, 139, 0.16) 0 0.18rem, transparent 0.19rem),
    rgba(229, 239, 255, 0.46);
  background-size: 2.4rem 2.4rem;
  border-radius: 0.55rem;
}

/* ===== src/windows/extensions.css ===== */
#rm_extensions_block {
  border-top: 3px solid #8cb8eb;
}

#rm_extensions_block :is(.extension_block, .extension-settings, .inline-drawer-content) {
  color: var(--mte-ink);
  background:
    linear-gradient(135deg, rgba(95, 136, 215, 0.11) 25%, transparent 25%) 0 0 / 1.4rem 1.4rem,
    linear-gradient(315deg, rgba(109, 90, 152, 0.08) 25%, transparent 25%) 0 0 / 1.4rem 1.4rem,
    rgba(255, 252, 246, 0.86);
  border-color: var(--mte-paper-edge);
  border-radius: 0.35rem 0.9rem;
}

#rm_extensions_block :is(.standoutHeader, .inline-drawer-header, h3, h4) {
  color: var(--mte-pool);
  text-shadow: none;
  filter: none;
}

#rm_extensions_block :is(#extensions_settings, #extensions_settings2) .inline-drawer-toggle.inline-drawer-header {
  color: var(--mte-pool);
  text-shadow: none;
  filter: none;
}

#extensionsMenu {
  color: var(--mte-ink);
  background: var(--mte-paper);
  border: 1px solid var(--mte-paper-edge);
  box-shadow: var(--mte-control-shadow);
  text-shadow: none;
}

#extensionsMenu :is(.extensionsMenuExtensionButton, .fa-solid) {
  color: var(--mte-pool);
  filter: none;
  text-shadow: none;
}

/* ===== src/windows/persona.css ===== */
#PersonaManagement {
  border-top: 3px solid #dba8c6;
}

#PersonaManagement :is(.avatar-container, .persona_block, .persona_description) {
  color: var(--mte-ink);
  background:
    linear-gradient(90deg, rgba(219, 168, 198, 0.16) 0 0.35rem, transparent 0.35rem),
    rgba(255, 252, 246, 0.9);
  border-color: color-mix(in srgb, #dba8c6 48%, var(--mte-paper-edge));
  border-radius: 0.3rem 1.15rem 0.3rem 0.3rem;
  box-shadow: 0 3px 0 rgba(95, 136, 215, 0.12);
}

#PersonaManagement .avatar img {
  border-color: var(--mte-water);
  box-shadow: 0 0 0 3px rgba(242, 154, 139, 0.18);
}

#PersonaManagement :is(.ch_name, .persona_name) {
  color: var(--mte-pool);
  text-shadow: none;
}

/* ===== src/windows/character.css ===== */
#right-nav-panel {
  border-left: 2px solid var(--mte-coral);
}

#right-nav-panel :is(.character_select, .group_select, .bogus_folder_select, #rm_print_characters_block) {
  color: var(--mte-ink);
}

#right-nav-panel :is(.character_select, .group_select, .bogus_folder_select) {
  background:
    linear-gradient(90deg, rgba(95, 136, 215, 0.15) 0 0.3rem, transparent 0.3rem),
    rgba(255, 252, 246, 0.9);
  border-color: color-mix(in srgb, var(--mte-water) 42%, var(--mte-paper-edge));
  border-radius: 0.25rem 1rem 1rem 0.25rem;
  box-shadow: 0 3px 0 rgba(242, 154, 139, 0.12);
}

#right-nav-panel .avatar img {
  border-color: var(--mte-water);
  box-shadow: 0 0 0 2px rgba(242, 154, 139, 0.18);
}

#right-nav-panel :is(.ch_name, .character_name_block) {
  color: var(--mte-pool);
  text-shadow: none;
}

#right-nav-panel :is(.tag, .tag_name) {
  color: var(--mte-pool);
  background: #e6efff;
  border-color: #9ebbe8;
  text-shadow: none;
  filter: none;
}

#right-nav-panel #rm_print_characters_block {
  background:
    repeating-linear-gradient(0deg, transparent 0 2.8rem, rgba(95, 136, 215, 0.08) 2.8rem 2.86rem),
    rgba(255, 248, 235, 0.56);
}

/* ===== src/windows/popup-notify.css ===== */
.popup {
  color: var(--mte-ink);
  background: linear-gradient(180deg, rgba(255, 248, 235, 0.92), rgba(248, 236, 223, 0.88));
  border-color: var(--mte-paper-edge);
  box-shadow: 0 24px 70px rgba(16, 25, 52, 0.3);
  backdrop-filter: var(--mte-frost);
  -webkit-backdrop-filter: var(--mte-frost);
  text-shadow: none;
}

.popup[open]::backdrop {
  background: rgba(16, 25, 52, 0.58);
  backdrop-filter: none;
}

.popup .popup-button-close {
  position: relative;
  min-width: 2.4rem;
  min-height: 2.4rem;
  color: var(--mte-pool);
  background: var(--mte-paper);
  border: 1px solid var(--mte-paper-edge);
  filter: none;
  text-shadow: none;
}

.popup .popup-button-close::before {
  content: "" !important;
  display: block;
  width: 2.4rem;
  height: 2.4rem;
  background-image: var(--mte-object-stop);
  background-position: center;
  background-repeat: no-repeat;
  background-size: contain;
  pointer-events: none;
}

.popup-controls .menu_button.popup-button-ok {
  color: var(--mte-paper);
  background: var(--mte-pool);
  border-color: var(--mte-pool);
}

body #toast-container > div {
  color: var(--mte-ink);
  background-color: var(--mte-paper);
  background-image: none !important;
  background-repeat: no-repeat;
  border: 1px solid var(--mte-paper-edge);
  border-left-width: 5px;
  border-radius: 0.45rem;
  box-shadow: var(--mte-control-shadow);
  opacity: 1;
  filter: none;
  text-shadow: none;
  padding-left: 1rem;
}

body #toast-container .toast-success { border-left-color: var(--mte-success); }
body #toast-container .toast-error { border-left-color: var(--mte-warning); }
body #toast-container .toast-info { border-left-color: var(--mte-water); }
body #toast-container .toast-warning { border-left-color: var(--mte-coral); }

body #toast-container :is(.toast-title, .toast-message, .toast-message a, .toast-close-button) {
  color: var(--mte-ink);
  text-shadow: none;
  filter: none;
}

body #toast-container .toast-progress {
  background: linear-gradient(90deg, var(--mte-water), var(--mte-coral));
  opacity: 0.85;
}

body #toast-container :is(.toast-close-button, a, button):focus-visible {
  outline: 2px solid var(--mte-focus);
  outline-offset: 2px;
}

/* ===== src/windows/mobile.css ===== */
@media screen and (max-width: 1000px) {
  #bg1,
  #bg_custom {
    background-attachment: scroll;
    background-position: center 45%;
  }

  #chat .mes {
    gap: 0.42rem;
    padding: 0.58rem 0.48rem;
  }

  #chat .mes[is_user="false"][is_system="false"] .mes_text,
  #chat .mes[is_user="false"][is_system="false"] .mes_reasoning {
    max-width: 100%;
  }

  #top-bar {
    border-bottom-width: 1px;
  }

  #top-settings-holder .drawer-icon {
    padding-inline: 0.12rem;
    transform: none;
  }

  :is(
    #leftNavDrawerIcon,
    #API-status-top,
    #advanced-formatting-button .drawer-icon,
    #WIDrawerIcon,
    #user-settings-button .drawer-icon,
    #backgrounds-button #backgrounds-drawer-toggle .drawer-icon,
    #extensions-settings-button .drawer-icon,
    #persona-management-button .drawer-icon,
    #rightNavDrawerIcon
  )::before {
    width: 1.9rem;
    height: 1.9rem;
  }

  #send_form :is(
    #options_button,
    #extensionsMenuButton,
    #send_but,
    #mes_continue,
    #mes_impersonate,
    .mes_stop,
    #rightSendForm .stscript_btn
  )::before {
    width: 2.15rem;
    height: 2.15rem;
  }

  #send_form #send_but::before,
  #send_form :is(.mes_stop, .stscript_stop)::before {
    width: 2.55rem;
    height: 2.55rem;
  }

  #send_form {
    border-top-width: 2px;
    border-radius: 0.9rem 0.9rem 0 0;
  }

  #nonQRFormItems,
  #leftSendForm,
  #rightSendForm {
    flex-wrap: nowrap;
  }

  #leftSendForm,
  #rightSendForm {
    width: auto;
    min-width: 1.15em;
  }

  #send_textarea {
    min-width: 0;
    padding-inline: 0.4rem;
  }

  :is(#left-nav-panel, #right-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement) {
    border-radius: 0 0 0.9rem 0.9rem;
    box-shadow: 0 12px 34px rgba(20, 34, 89, 0.2);
  }

  :is(#left-nav-panel, #right-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement) :is(.inline-drawer-header, .drawer-header, .standoutHeader) {
    border-radius: 0.25rem 0.72rem 0.25rem 0.25rem;
  }

  #completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    grid-template-columns: minmax(0, 1fr) 4.2rem 2.5rem;
    padding: 0.45rem;
  }

  #WorldInfo #WIMultiSelector .select2-container .select2-selection--multiple {
    max-height: 22vh;
  }
}

@media screen and (max-width: 430px) {
  #chat .mes {
    padding-inline: 0.4rem;
  }

  #chat .mes_text,
  #chat .mes_reasoning {
    line-height: 1.78;
  }
}

@media screen and (max-width: 390px) {
  #completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    grid-template-columns: minmax(0, 1fr) 3.65rem 2.2rem;
  }
}

@media screen and (max-width: 360px) {
  #chat .mes {
    gap: 0.3rem;
    padding-inline: 0.3rem;
  }

  #send_form {
    border-inline-width: 1px;
  }
}

/* ===== src/fallback.css ===== */
#bg1,
#bg_custom {
  background-color: var(--mte-night);
}

#top-settings-holder .drawer-icon,
#options_button,
#extensionsMenuButton,
#send_but,
#send_form .mes_stop,
#rightSendForm .stscript_btn {
  pointer-events: auto;
}
